## 4. Core Features – Code Snippets

### 4.1 Product Listing Page (`pages/index.tsx`)

```tsx
import { useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { fetchProducts } from '@/store/productSlice';
import ProductCard from '@/components/product/ProductCard';
import { RootState } from '@/store';

export default function Home() {
  const dispatch = useDispatch();
  const { items, status } = useSelector((state: RootState) => state.products);

  useEffect(() => {
    if (status === 'idle') dispatch(fetchProducts());
  }, [dispatch, status]);

  if (status === 'loading') return <p>Loading…</p>;
  if (status === 'failed') return <p>Failed to load products.</p>;

  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
      {items.map((p) => (
        <ProductCard key={p.id} product={p} />
      ))}
    </div>
  );
}
```

### 4.2 Product Card (`components/product/ProductCard.tsx`)

```tsx
import Link from 'next/link';
import Image from 'next/image';
import { Product } from '@/types';

interface Props {
  product: Product;
}

export default function ProductCard({ product }: Props) {
  return (
    <Link href={`/product/${product.slug}`}>
      <a className="block border rounded-lg overflow-hidden hover:shadow-lg transition-shadow">
        <Image
          src={product.image}
          alt={product.title}
          width={400}
          height={400}
          className="object-cover w-full h-48"
        />
        <div className="p-4">
          <h3 className="font-semibold text-lg">{product.title}</h3>
          <p className="text-gray-600">${product.price.toFixed(2)}</p>
        </div>
      </a>
    </Link>
  );
}
```

### 4.3 Cart Slice (`store/cartSlice.ts`)

```ts
import { createSlice, PayloadAction } from '@reduxjs/toolkit';
import { Product } from '@/types';

interface CartItem extends Product {
  quantity: number;
}

interface CartState {
  items: CartItem[];
}

const initialState: CartState = { items: [] };

const cartSlice = createSlice({
  name: 'cart',
  initialState,
  reducers: {
    addToCart(state, action: PayloadAction<Product>) {
      const existing = state.items.find((i) => i.id === action.payload.id);
      if (existing) {
        existing.quantity += 1;
      } else {
        state.items.push({ ...action.payload, quantity: 1 });
      }
    },
    removeFromCart(state, action: PayloadAction<string>) {
      state.items = state.items.filter((i) => i.id !== action.payload);
    },
    clearCart(state) {
      state.items = [];
    },
  },
});

export const { addToCart, removeFromCart, clearCart } = cartSlice.actions;
export default cartSlice.reducer;
```

### 4.4 Checkout Page (`pages/checkout.tsx`)

```tsx
import { useForm } from 'react-hook-form';
import { useDispatch } from 'react-redux';
import { clearCart } from '@/store/cartSlice';
import { useRouter } from 'next/router';
import { loadStripe } from '@stripe/stripe-js';

const stripePromise = loadStripe(process.env.NEXT_PUBLIC_STRIPE_PUBLISHABLE_KEY!);

export default function Checkout() {
  const { register, handleSubmit, formState: { errors } } = useForm();
  const dispatch = useDispatch();
  const router = useRouter();

  const onSubmit = async (data: any) => {
    const stripe = await stripePromise;
    const response = await fetch('/api/checkout', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data),
    });
    const session = await response.json();
    await stripe?.redirectToCheckout({ sessionId: session.id });
  };

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="max-w-xl mx-auto">
      {/* Billing fields */}
      <input {...register('email', { required: true })} placeholder="Email" />
      {/* ... other fields */}
      <button type="submit" className="btn-primary mt-4">Pay</button>
    </form>
  );
}
```

> **Tip** – The `/api/checkout` route should create a Stripe Checkout Session on the server.

---

## 5. API Integration

### 5.1 RTK Query Setup (`services/api.ts`)

```ts
import { createApi, fetchBaseQuery } from '@reduxjs/toolkit/query/react';

export const api = createApi({
  reducerPath: 'api',
  baseQuery: fetchBaseQuery({ baseUrl: '/api' }),
  endpoints: (builder) => ({
    getProducts: builder.query<Product[], void>({
      query: () => 'products',
    }),
    getProductBySlug: builder.query<Product, string>({
      query: (slug) => `products/${slug}`,
    }),
    // ... more endpoints
  }),
});

export const { useGetProductsQuery, useGetProductBySlugQuery } = api;
```

### 5.2 Server‑Side API Example (`pages/api/products/[slug].ts`)

```ts
import type { NextApiRequest, NextApiResponse } from 'next';
import { prisma } from '@/lib/prisma';

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { slug } = req.query;
  const product = await prisma.product.findUnique({
    where: { slug: slug as string },
    include: { images: true, reviews: true },
  });

  if (!product) return res.status(404).json({ error: 'Not found' });

  res.json(product);
}
```

---

## 6. Authentication & Authorization

| Feature | Implementation |
|---------|----------------|
| **Login / Register** | `next-auth` with email/password or OAuth (Google, Facebook) |
| **Session** | JWT stored in HTTP‑Only cookie |
| **Role‑based access** | Store `role` in session; guard admin routes with `getServerSideProps` |

```tsx
// pages/admin/products.tsx
import { getSession } from 'next-auth/react';

export const getServerSideProps = async (ctx) => {
  const session = await getSession(ctx);
  if (!session || session.user.role !== 'admin') {
    return { redirect: { destination: '/login', permanent: false } };
  }
  return { props: {} };
};
```

---

## 7. Payment Integration

1. **Create a Stripe Checkout Session** on the server (`pages/api/checkout.ts`).
2. **Redirect** the user to Stripe’s hosted checkout page.
3. **Handle webhook** (`/api/webhooks/stripe`) to confirm payment and update order status.

```ts
// pages/api/checkout.ts
import { NextApiRequest, NextApiResponse } from 'next';
import Stripe from 'stripe';
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY!, { apiVersion: '2023-10-16' });

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { email, items } = req.body;
  const line_items = items.map((i: any) => ({
    price_data: {
      currency: 'usd',
      product_data: { name: i.title },
      unit_amount: Math.round(i.price * 100),
    },
    quantity: i.quantity,
  }));

  const session = await stripe.checkout.sessions.create({
    payment_method_types: ['card'],
    line_items,
    mode: 'payment',
    customer_email: email,
    success_url: `${process.env.NEXT_PUBLIC_APP_URL}/success?session_id={CHECKOUT_SESSION_ID}`,
    cancel_url: `${process.env.NEXT_PUBLIC_APP_URL}/cancel`,
  });

  res.json({ id: session.id });
}
```

---

## 8. Performance & SEO

| Technique | How |
|-----------|-----|
| **SSR/SSG** | Next.js pages pre-rendered at build time or request time |
| **Image Optimization** | `next/image` with `layout="responsive"` |
| **Code Splitting** | Dynamic imports (`next/dynamic`) |
| **Lazy Loading** | `loading="lazy"` on images, `react-intersection-observer` for components |
| **Caching** | SWR or RTK Query caching, CDN edge caching |
| **SEO** | `<Head>` meta tags, Open Graph, structured data (JSON‑LD) |
| **Accessibility** | ARIA roles, semantic HTML, keyboard navigation, color contrast |

---

## 9. Testing

### 9.1 Unit Test Example (`components/product/ProductCard.test.tsx`)

```tsx
import { render, screen } from '@testing-library/react';
import ProductCard from './ProductCard';
import { Product } from '@/types';

const mockProduct: Product = {
  id: '1',
  title: 'Test Shirt',
  price: 29.99,
  slug: 'test-shirt',
  image: '/test.jpg',
};

test('renders product card', () => {
  render(<ProductCard product={mockProduct} />);
  expect(screen.getByText(/Test Shirt/i)).toBeInTheDocument();
  expect(screen.getByText(/\$29\.99/i)).toBeInTheDocument();
});
```

### 9.2 Integration Test Example (`pages/index.test.tsx`)

```tsx
import { render, screen, waitFor } from '@testing-library/react';
import Home from '@/pages/index';
import { Provider } from 'react-redux';
import { store } from '@/store';

global.fetch = jest.fn(() =>
  Promise.resolve({
    json: () => Promise.resolve([{ id: '1', title: 'Test', price: 10, slug: 'test', image: '/test.jpg' }]),
  })
);

test('loads and displays products', async () => {
  render(
    <Provider store={store}>
      <Home />
    </Provider>
  );
  await waitFor(() => expect(screen.getByText(/Test/i)).toBeInTheDocument());
});
```

